        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Kim inkar ederse, inkarı kendi aleyhine olur. Yararlı iş işleyen kimseler, kendileri için rahat bir yer hazırlamış olurlar"
        }
